/**
 * Copies the SQL migrations generated by drizzle-kit (./drizzle/*.sql, in journal order) into
 * src/migrations.generated.ts, so that they are part of the bundle: nothing is read from disk at
 * runtime, which is what makes getDb() work inside a Next.js server bundle on Vercel.
 *
 * Run by `pnpm --filter @nait/db db:generate`.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const journal = JSON.parse(readFileSync(join(root, 'drizzle/meta/_journal.json'), 'utf8')) as {
  entries: { idx: number; tag: string }[];
};

const migrations = [...journal.entries]
  .sort((a, b) => a.idx - b.idx)
  .map((entry) => ({
    id: entry.tag,
    statements: readFileSync(join(root, 'drizzle', `${entry.tag}.sql`), 'utf8')
      .split('--> statement-breakpoint')
      .map((statement) => statement.trim())
      .filter((statement) => statement.length > 0),
  }));

const lines = [
  '// AUTO-GENERATED from ./drizzle/*.sql by scripts/embed-migrations.ts. Do not edit by hand.',
  '// Regenerate with: pnpm --filter @nait/db db:generate',
  '',
  'export interface Migration {',
  '  /** File name of the migration without extension, e.g. "0000_init". */',
  '  id: string;',
  '  /** SQL statements, executed in order inside one transaction. */',
  '  statements: string[];',
  '}',
  '',
  'export const migrations: Migration[] = [',
  ...migrations.flatMap((migration) => [
    '  {',
    `    id: ${JSON.stringify(migration.id)},`,
    '    statements: [',
    ...migration.statements.map((statement) => `      ${JSON.stringify(statement)},`),
    '    ],',
    '  },',
  ]),
  '];',
  '',
];

writeFileSync(join(root, 'src/migrations.generated.ts'), lines.join('\n'));
console.log(
  `src/migrations.generated.ts: ${migrations.length} migration(s), ` +
    `${migrations.reduce((n, m) => n + m.statements.length, 0)} statement(s)`,
);
